package com.honorablemobile

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
class VideoScriptCaptionReviewTest {
 private val unsafe=Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe").apply{isAccessible=true}.get(null)as sun.misc.Unsafe
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun pair(a:HonorableVideoEditorActivity):Pair<AlertDialog,AlertDialog>{val editor=dialog();val confirmation=dialog();set(a,"scriptCaptionEditor",editor);set(a,"scriptCaptionConfirmation",confirmation);set(a,"captionReviewDialogs",linkedSetOf(editor,confirmation));return editor to confirmation}
 private fun cues(clip:VideoSegment)=VideoStoryTools.scriptCaptions(clip,"First line\nSecond longer line")
 private fun apply(a:HonorableVideoEditorActivity,pair:Pair<AlertDialog,AlertDialog>,review:VideoCaptionReviewState,p:VideoEditProject=get(a,"project")as VideoEditProject,index:Int=0,clip:VideoSegment=p.segments[0],proposed:List<VideoCaption> = cues(clip))=call(a,"commitScriptCaptionReview",pair.first,pair.second,review,p,index,clip,proposed)as Boolean
 @Test fun pausedScriptEntryReturnsBeforeWidgets(){val a=activity();set(a,"workspaceActive",false);call(a,"scriptCaptionOptions");assertNull(get(a,"scriptCaptionEditor"));assertNull(get(a,"scriptCaptionConfirmation"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}
 @Test fun currentVisiblePairKeepsSubtitleDocumentMusicAndOneUndo(){val a=activity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val music=p.soundtrack;val pair=pair(a);val review=capture(a);assertTrue(apply(a,pair,review));assertEquals(cues(old[0]),p.segments[0].captions);assertEquals(old[0].captionSourceUri,p.segments[0].captionSourceUri);assertTrue(p.captionSourceUris().contains("content://synthetic/subtitles"));assertSame(music,p.soundtrack);assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());assertEquals(cues(old[0]),p.segments[0].captions)}
 @Test fun eitherUntrackedDialogRejectsWithoutHistory(){for(which in listOf(0,1)){val a=activity();val p=get(a,"project")as VideoEditProject;val pair=pair(a);val review=capture(a);set(a,"captionReviewDialogs",linkedSetOf(if(which==0)pair.second else pair.first));assertFalse(apply(a,pair,review));assertFalse(p.canUndo)}}
 @Test fun eitherReplacedOwnerRejectsEvenIfOldDialogsStillVisible(){for(field in listOf("scriptCaptionEditor","scriptCaptionConfirmation")){val a=activity();val p=get(a,"project")as VideoEditProject;val pair=pair(a);val review=capture(a);set(a,field,dialog());assertFalse(apply(a,pair,review));assertFalse(p.canUndo)}}
 @Test fun eitherDismissedDecorRejectsBeforeMembershipRemoval(){for(which in listOf(0,1)){val a=activity();val p=get(a,"project")as VideoEditProject;val pair=pair(a);val review=capture(a);showing(if(which==0)pair.first else pair.second,false);assertFalse(apply(a,pair,review));assertFalse(p.canUndo)}}
 @Test fun staleSessionGenerationSourceDurationMusicRangeRecoveryOrBusyRejects(){for(flag in listOf("pause","generation","mode","source","duration","music","range","recovery","busy")){val a=activity();val p=get(a,"project")as VideoEditProject;val pair=pair(a);val review=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"generation"->set(a,"captionReviewGeneration",review.generation+1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",6000L);"music"->p.setSoundtrack(p.soundtrack!!.copy(volume=.5f));"range"->set(a,"selectedClip",1);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));else->set(a,"saving",true)};val before=p.segments;assertFalse(flag,apply(a,pair,review));assertSame(before,p.segments)}}
 @Test fun cancelledConfirmationCannotReviveThroughUndo(){val a=activity();val p=get(a,"project")as VideoEditProject;val pair=pair(a);val review=capture(a);assertTrue(apply(a,pair,review));set(a,"scriptCaptionConfirmation",null);assertTrue(p.undo());assertEquals(true,call(a,"canApplyCaptionReview",review));assertFalse(apply(a,pair,review));assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun foreignProjectIndexOrClipCannotUseCurrentApproval(){for(flag in listOf("project","index","clip")){val a=activity();val p=get(a,"project")as VideoEditProject;val pair=pair(a);val review=capture(a);val old=p.segments[0];val foreign=VideoEditProject(5000);assertFalse(apply(a,pair,review,if(flag=="project")foreign else p,if(flag=="index")1 else 0,if(flag=="clip")old.copy(title="Foreign")else old));assertFalse(p.canUndo);assertFalse(foreign.canUndo)}}
 @Test fun invalidGeneratedCueCollectionFailsBeforeMutation(){val a=activity();val p=get(a,"project")as VideoEditProject;val pair=pair(a);val review=capture(a);val old=p.segments;try{apply(a,pair,review,proposed=listOf(VideoCaption(0,1000,"A"),VideoCaption(500,1500,"B")));fail("Applied overlap")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalArgumentException)};assertSame(old,p.segments);assertFalse(p.canUndo)}
 @Test fun originalAuthoredLinesAndRecoveryRemainIntact(){val original=VideoSegment(1000,7000,speed=2f,captionSourceUri="content://synthetic/subtitles");val proposed=VideoStoryTools.scriptCaptions(original," First line \n\n Second longer line ");assertEquals(listOf("First line","Second longer line"),proposed.map{it.text});assertEquals(1000L,proposed.first().startMs);assertEquals(7000L,proposed.last().endMs);assertEquals(proposed[0].endMs,proposed[1].startMs);val draft=VideoDraft(8000,listOf(original.copy(captions=proposed)),0,1000,1000,7000);val restored=requireNotNull(VideoDraftCodec.decode(VideoDraftCodec.encode(draft),8000));assertEquals(draft,restored);assertEquals("content://synthetic/subtitles",restored.segments[0].captionSourceUri);assertEquals(3000000L,VideoCaptions.resolve(restored.segments).last().endUs)}
}
